/* =============================================================================
 * 以下为规范落地新增的通用组件
 * ========================================================================== */

/* ---------- 轻提示 ---------- */
.mtl-toast{
  position:fixed;left:50%;bottom:56px;transform:translate(-50%,12px);
  max-width:min(720px,86vw);
  background:var(--ink);color:#fff;
  font-size:var(--fs-sm);line-height:1.65;
  padding:10px 18px;border-radius:var(--r);
  box-shadow:var(--sh-lg);
  opacity:0;pointer-events:none;transition:opacity .18s,transform .18s;
  z-index:200;
}
.mtl-toast.on{opacity:1;transform:translate(-50%,0)}
.mtl-toast.err{background:var(--red)}

/* ---------- 字段示例说明 ---------- */
.fld-hint{font-size:11.6px;line-height:1.6;color:var(--ink-40);margin-top:5px}
.fld-hint b{color:var(--ink-60)}
.fld-hint.err,{color:var(--red)}
.err{color:var(--red)}
.req{color:var(--red);font-style:normal;margin-left:2px}

/* ---------- 两段式进度条（一级标题：常规 / 悬浮 / 选中） ---------- */
.stagebar{display:flex;gap:10px;margin-bottom:14px;flex-wrap:wrap}
.stagebar .sg{
  flex:1 1 240px;display:flex;align-items:center;gap:10px;
  background:var(--card);border:1px solid var(--line);border-radius:var(--r);
  padding:11px 14px;transition:.16s;
}
.stagebar .sg .n{
  width:24px;height:24px;flex:0 0 auto;border-radius:50%;
  display:inline-flex;align-items:center;justify-content:center;
  background:var(--bg-soft);color:var(--ink-40);font-size:var(--fs-sm);font-weight:700;
}
.stagebar .sg b{display:block;font-size:var(--fs-base);color:var(--ink);line-height:1.4}
.stagebar .sg small{display:block;font-size:11.4px;color:var(--ink-40);line-height:1.5}
.stagebar .sg:hover{border-color:var(--brand-40);background:var(--brand-ll)}
.stagebar .sg.on{border-color:var(--brand);background:var(--brand-ll)}
.stagebar .sg.on .n{background:var(--brand);color:#fff}
.stagebar .sg.on b{color:var(--brand-d)}

/* ---------- 紧凑表格 ---------- */
.bt.mini{font-size:12.1px}
.bt.mini th{padding:8px 10px;font-size:11.8px;background:var(--bg-soft)}
.bt.mini td{padding:8px 10px;border-bottom:1px solid var(--line2);white-space:normal;word-break:break-word}
.bt.mini tbody tr:nth-child(even){background:transparent}
.bt.mini tbody tr:hover{background:var(--brand-ll)}
.bt td.idx{color:var(--ink-40);font-variant-numeric:tabular-nums}
.bt .del{color:var(--red);cursor:pointer;font-weight:600}
.bt .del:hover{text-decoration:underline}
.bt .ro{color:var(--ink-80)}
.bt .empty-row{color:var(--ink-40);text-align:center;padding:18px 10px}
.bt .ci{width:100%;border:1px solid var(--line);border-radius:var(--r-sm);padding:4px 8px;font-size:12.1px}

pages/plan-batch.css:
/* =============================================================================
 * 名单导入抽屉（标黄项 10 / 11）
 * ========================================================================== */
.imp-drop{
  display:flex;align-items:center;gap:16px;flex-wrap:wrap;
  border:1.5px dashed var(--brand-40);border-radius:var(--r);
  background:var(--brand-ll);padding:14px 16px;margin:14px 0;
}
.imp-drop-l{flex:1 1 220px}
.imp-drop-l b{display:block;font-size:var(--fs-base);color:var(--brand-d)}
.imp-drop-l small{display:block;font-size:11.6px;color:var(--ink-60);margin-top:3px}
.imp-drop-r{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.imp-drop-r input[type=file]{font-size:11.8px;max-width:220px}
.imp-paste{width:100%;font-family:var(--font-mono);font-size:11.8px;line-height:1.7;min-height:96px}
.imp-preview{max-height:320px;overflow:auto;border:1px solid var(--line);border-radius:var(--r)}
.imp-tbl tr.imp-bad td{background:var(--red-ll)}
.imp-tbl .tg{white-space:normal;line-height:1.5}

/* =============================================================================
 * 补充批次信息抽屉（标黄项 3）
 * ========================================================================== */
.dw-batch{width:880px}
.bat-grid{display:grid;grid-template-columns:minmax(0,1fr) 268px;gap:24px;align-items:start}
.bat-form .fr{margin-bottom:14px}
.bat-side .psec{margin-top:0}
.wxcard{
  display:flex;align-items:stretch;gap:12px;
  border:1px solid var(--line);border-radius:var(--r);overflow:hidden;
  background:var(--card);box-shadow:var(--sh);
}
.wxcard-l{
  flex:0 0 108px;background:var(--brand);color:#fff;
  display:flex;flex-direction:column;align-items:center;justify-content:center;
  gap:4px;padding:16px 8px;
}
.wxcard-l .amt{font-size:var(--fs-sm)}
.wxcard-l .amt b{font-size:var(--fs-2xl)}
.wxcard-l .thr{font-size:10.5px;opacity:.86}
.wxcard-r{flex:1;min-width:0;padding:12px 14px;display:flex;flex-direction:column;gap:3px}
.wxcard-r b{font-size:var(--fs-base);color:var(--ink)}
.wxcard-r small{font-size:11.4px;color:var(--ink-60)}
.wxcard-r small.mut{color:var(--ink-40);line-height:1.5}
@media (max-width:1000px){
  .bat-grid{grid-template-columns:1fr}
  .dw-batch{width:100%}
}

pages/coupon.css:
/* =============================================================================
 * 分渠道二维码（标黄项 16）
 * ========================================================================== */
.qwrap2{display:grid;grid-template-columns:288px minmax(0,1fr);gap:20px;align-items:start;margin-top:4px}
.qrc-list{
  border:1px solid var(--line);border-radius:var(--r);
  background:var(--card);padding:8px;max-height:420px;overflow:auto;
}
.qrc-grp{border-radius:var(--r-sm);margin-bottom:6px}
.qrc-grp.on{background:var(--brand-ll);border:1px solid var(--brand-20)}
.qrc-h{
  display:flex;align-items:center;gap:6px;
  padding:8px 10px;border-radius:var(--r-sm);cursor:pointer;
  font-size:var(--fs-sm);color:var(--ink);
}
.qrc-h:hover{background:var(--bg-soft)}
.qrc-h b{font-weight:600}
.qrc-h .tag{
  font-family:var(--font-mono);font-size:10px;color:var(--brand-d);
  background:var(--brand-l);border-radius:3px;padding:0 4px;line-height:16px;
}
.qrc-h .cnt{margin-left:auto;font-size:11px;color:var(--ink-40)}
.qrc-b{padding:6px 8px 10px}
.qrc-item{
  display:flex;align-items:center;gap:6px;
  padding:5px 8px;border-radius:var(--r-sm);cursor:pointer;
  font-size:11.6px;color:var(--ink-80);
}
.qrc-item .nm{font-family:var(--font-mono);font-size:10.6px}
.qrc-item .mut{margin-left:auto;font-size:10.5px}
.qrc-item:hover{background:var(--card)}
.qrc-item.cur{background:var(--card);box-shadow:0 0 0 1px var(--brand-40);color:var(--brand-d);font-weight:600}
.qrc-main{display:grid;grid-template-columns:184px minmax(0,1fr);gap:22px;align-items:start}
.qrc-qr{text-align:center;padding-top:4px}
.qrc-qr .qr{width:150px;height:150px;margin:0 auto;padding:8px}
.qrc-info .psec{margin-top:16px}
@media (max-width:1000px){
  .qwrap2,.qrc-main{grid-template-columns:1fr}
}
